// Continuous H7/H8 tile family: one stable patch, changing geometry, explicit periodic exceptions.
import {makeExpandingFamilyWindow} from './gallery-hat-model.js';
import {exhibit,background,path,field,bind,button} from './gallery-kit.js';
const HAT=1/(1+Math.sqrt(3));
export function einsteinTiles(root,opts){
  const {t}=opts,family=makeExpandingFamilyWindow();let parameter=HAT,playing=false,phase=Math.asin(2*HAT-1),selected=null,tiles=[];
  // Fixed tile size; the hierarchy supplies neighbours in the camera's visible window.
  const scale=32;
  const o=exhibit(root,opts,t('Un seul pavé, une infinité de formes. Fais glisser le curseur : toutes les pièces se déforment ensemble et restent jointives. Le pavage se prolonge jusqu’aux bords de la vue. Touche une pièce pour suivre sa place dans le pavage. Molette ou pincement pour explorer les détails.','One tile, infinitely many shapes. Slide the control: every piece deforms together and keeps fitting. The tiling extends to the edges of the view. Tap a tile to follow its place in the patch. Wheel or pinch to explore details.'),
    field('hat-shape',t('Forme : a / (a + b)','Shape: a / (a + b)'),0,1,.001,HAT)+button('hat-play',t('Animer la famille','Animate the family'),true)+`<label class="act-check"><input id="hat-reflect" type="checkbox" checked>${t('Distinguer les pièces réfléchies','Highlight reflected tiles')}</label><div class="exhibit-presets">${[[0,t('Chevron','Chevron')],[HAT,t('Chapeau','Hat')],[.5,t('Équilatéral','Equilateral')],[1-HAT,t('Tortue','Turtle')],[1,t('Comète','Comet')]].map(([v,label])=>button(`hat-p${Math.round(v*10000)}`,label)).join('')}</div>`,
    `<p>${t('La famille Tile(a,b) est engendrée ici par la construction hiérarchique H7/H8. Chapeau : a:b = 1:√3 ; tortue : a:b = √3:1. Les couleurs signalent la réflexion, pas plusieurs formes de pavés.','The Tile(a,b) family is generated here by the H7/H8 hierarchy. Hat: a:b = 1:√3; turtle: a:b = √3:1. Colours mark reflection, not different tile shapes.')}</p><p>${t('Attention aux exceptions : a = 0, b = 0 et a = b admettent des pavages périodiques. Pour a,b > 0 et a ≠ b, la forme force l’apériodicité. Une portion finie ne prouve jamais à elle seule qu’un pavage infini est apériodique. La forme équilatérale à côtés droits n’est pas le Spectre à bords courbes.','Exceptions matter: a = 0, b = 0 and a = b admit periodic tilings. For a,b > 0 and a ≠ b, the shape forces aperiodicity. A finite patch alone never proves that an infinite tiling is aperiodic. The straight-edged equilateral shape is not the curved-edge Spectre.')}</p><p>${t('Construction mathématique : Smith, Myers, Kaplan et Goodman-Strauss, figure 2.11, An aperiodic monotile.','Mathematical construction: Smith, Myers, Kaplan and Goodman-Strauss, Figure 2.11, An aperiodic monotile.')} <a href="https://cs.uwaterloo.ca/~csk/hat/" target="_blank" rel="noopener noreferrer">${t('Article et application des auteurs','Paper and authors’ application')}</a> · <a href="https://cs.uwaterloo.ca/~csk/spectre/" target="_blank" rel="noopener noreferrer">Spectre</a></p>`);
  const g=o.g,screen=([x,y])=>[320+x*scale,220+y*scale],slider=root.querySelector('#hat-shape'),out=root.querySelector('#hat-shape-out');let reflected=true;
  function sync(){slider.value=parameter;out.textContent=parameter.toFixed(3);root.querySelector('#hat-play').textContent=playing?t('Suspendre','Pause'):t('Animer la famille','Animate the family');}
  bind(root,'hat-shape',v=>{parameter=v;playing=false;sync();o.redraw();},v=>v.toFixed(3));
  for(const v of [0,HAT,.5,1-HAT,1])o.on(root.querySelector(`#hat-p${Math.round(v*10000)}`),'click',()=>{parameter=v;playing=false;sync();o.redraw();});
  o.on(root.querySelector('#hat-reflect'),'change',e=>{reflected=e.target.checked;o.redraw();});
  o.on(root.querySelector('#hat-play'),'click',()=>{playing=!playing;phase=Math.asin(2*parameter-1);root.querySelector('#hat-play').textContent=playing?t('Suspendre','Pause'):t('Animer la famille','Animate the family');if(opts.reduced()){playing=false;parameter=parameter<.5?1-HAT:HAT;sync();o.redraw();}sync();});
  function inside(p,poly){let hit=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])hit=!hit;}return hit;}
  o.on(o.cv,'pointerdown',e=>{const p=o.point(e);selected=tiles.find(tile=>inside(p,tile.vertices.map(screen)))?.id??null;o.redraw();});
  o.on(o.cv,'keydown',e=>{if(e.shiftKey)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();parameter=Math.max(0,Math.min(1,parameter+(e.key==='ArrowRight'?.01:-.01)));playing=false;sync();o.redraw();}sync();});
  let frame=0,lastKey='';
  o.animate(dt=>{if(playing&&dt){phase+=dt*.25;parameter=(Math.sin(phase)+1)/2;sync();}const camera=o.navigation.camera,key=[parameter,selected,reflected,camera.scale,camera.x,camera.y,document.documentElement.dataset.theme].join(',');if(key===lastKey)return;lastKey=key;const a=camera.unproject([0,0]),b=camera.unproject([640,440]);tiles=family(parameter,[(a[0]-320)/scale-1,(a[1]-220)/scale-1,(b[0]-320)/scale+1,(b[1]-220)/scale+1]);const C=background(o);
    tiles.forEach(tile=>path(g,tile.vertices.map(screen),{close:true,fill:tile.id===selected?C.obj2:tile.reflected&&reflected?C.obj3:C.accent,stroke:C.surface,width:.8,alpha:tile.id===selected?.95:tile.reflected&&reflected?.8:.37}));
    const exception=parameter<1e-9||parameter>1-1e-9||Math.abs(parameter-.5)<1e-9;
    if(++frame%12===0||!dt)o.read(`a = ${parameter.toFixed(3)}, b = ${(1-parameter).toFixed(3)} · ${tiles.length} ${t('pièces dans la fenêtre','tiles in this window')}. ${exception?t('Exception : cette forme admet aussi des pavages périodiques.','Exception: this shape also admits periodic tilings.'):t('Forme apériodique ; le dessin montre une portion finie.','Aperiodic shape; this drawing shows a finite patch.')}`);
  });return o.stop;
}
